before:
Complete local Go example; the app itself does not execute it:
```go
package main

import (
"fmt"
"sync"
)


func main() {
    var mu sync.Mutex
    var wg sync.WaitGroup
    count := 0
    wg.Add(2)
    for worker := 0; worker < 2; worker++ {
        go func() {
            defer wg.Done()
            for i := 0; i < 100; i++ { mu.Lock(); count++; mu.Unlock() }
        }()
    }
    wg.Wait()
    fmt.Println(count)
}
```

